-- استرجاع v204: سياسة تعديل الانتداب كما كانت (بلا منسق المرحلة)
drop policy if exists delegations_update on public.delegations;
create policy delegations_update on public.delegations for update to authenticated
using (((( SELECT current_app_role() AS current_app_role) = ANY (ARRAY['admin'::app_role, 'first_supervisor'::app_role])) OR ((( SELECT current_app_role() AS current_app_role) = 'supervisor'::app_role) AND (can_access_school(from_school_id) OR can_access_school(to_school_id))) OR ((( SELECT current_app_role() AS current_app_role) = 'senior_teacher'::app_role) AND ((from_school_id = ( SELECT current_home_school_id() AS current_home_school_id)) OR (to_school_id = ( SELECT current_home_school_id() AS current_home_school_id))))))
with check (((( SELECT current_app_role() AS current_app_role) = ANY (ARRAY['admin'::app_role, 'first_supervisor'::app_role])) OR ((( SELECT current_app_role() AS current_app_role) = 'supervisor'::app_role) AND (can_access_school(from_school_id) OR can_access_school(to_school_id))) OR ((( SELECT current_app_role() AS current_app_role) = 'senior_teacher'::app_role) AND ((from_school_id = ( SELECT current_home_school_id() AS current_home_school_id)) OR (to_school_id = ( SELECT current_home_school_id() AS current_home_school_id))))));
